{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.Offline_metrics_warehouse_stock AS SELECT a.*, b.CATEGORY as Product_type, b.OCCASSION_NEW AS OCCASSION, b.DESIGNS AS PRINT_DESIGN, b.COLLAR_NEW AS COLLAR, b.MATERIAL_NEW AS MATERIAL, b.SLEEVE_TYPE, b.FIT, b.STYLE, b.COLOR, b.CLOSURE, b.LENGTH, c.image_link FROM snitch_db.maplemonk.availability_master_v2 a LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) AS rn FROM snitch_db.maplemonk.metafields_data ) WHERE rn = 1 ) b ON LOWER(a.sku_group) = LOWER(b.sku_group) LEFT JOIN ( SELECT * FROM ( WITH product_images AS ( SELECT DISTINCT id, REPLACE(A.value:src, \'\"\', \'\') AS src, REPLACE(A.value:position, \'\"\', \'\') AS pst FROM snitch_db.maplemonk.shopifyindia_new_products, LATERAL FLATTEN(INPUT => IMAGES) A WHERE REPLACE(A.value:position, \'\"\', \'\') = \'1\' ) SELECT b.sku_group, a.src AS image_link, ROW_NUMBER() OVER (PARTITION BY b.sku_group ORDER BY b.sku_group) AS rn FROM product_images a LEFT JOIN snitch_db.maplemonk.availability_master_v2 b ON a.id = b.id ) WHERE rn = 1 ) c ON LOWER(a.sku_group) = LOWER(c.sku_group); Create or replace table snitch_db.maplemonk.Offline_metrics as SELECT A.*, B.AM, B.RM, B.NSM, B.CITY, B.STATE, B.REGION, B.partner FROM snitch_db.maplemonk.Offline_Detailed_Summary AS A LEFT JOIN snitch_db.maplemonk.master_offine AS B ON A.BRANCH_CODE = B.\"BRANCH CODE\" WHERE A.marketplace_mapped NOT LIKE \'%- WH -%\' ; Create Or REPLACE Table snitch_db.maplemonk.Offline_Inventory_aging as WITH InventoryAging AS ( SELECT branch_code, BRANCH_NAME, REVERSE(SUBSTRING(REVERSE(LOGICUSERCODE), CHARINDEX(\'-\', REVERSE(LOGICUSERCODE)) + 1)) AS sku_group, SUM(stock_qty) AS total_inventory, DATEDIFF(DAY, TO_DATE(lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE) AS Age FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE DATE = CURRENT_DATE AND LOGICUSERCODE NOT LIKE (\'CB%\') GROUP BY branch_code, REVERSE(SUBSTRING(REVERSE(LOGICUSERCODE), CHARINDEX(\'-\', REVERSE(LOGICUSERCODE)) + 1)), TO_DATE(lot_pur_date, \'DD/MM/YYYY\'), BRANCH_NAME ), WeightedAging AS ( SELECT branch_code, BRANCH_NAME, sku_group, SUM(total_inventory * Age) AS total_weighted_age, SUM(total_inventory) AS total_inventory FROM InventoryAging GROUP BY branch_code, sku_group,BRANCH_NAME ), age as ( SELECT branch_code, BRANCH_NAME, sku_group, total_inventory, CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) AS final_weighted_age, CASE WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 30 THEN \'0-30\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 60 THEN \'31-60\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 90 THEN \'61-90\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 180 THEN \'91-180\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 360 THEN \'181-360\' ELSE \'>360\' END AS aging_interval FROM WeightedAging ORDER BY branch_code, sku_group,BRANCH_NAME ), meta as (Select * from (SELECT *, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) AS rn FROM snitch_db.maplemonk.metafields_data)where rn=1) select a.*, b.CATEGORY from age a left join meta b on LOWER(a.sku_group)=LOWER(b.sku_group); Create Or REPLACE Table snitch_db.maplemonk.Offline_Inventory_aging_shivera as select * from snitch_db.maplemonk.Offline_Inventory_aging where BRANCH_CODE IN (\'17\', \'38\', \'28\', \'36\', \'24\', \'26\', \'23\', \'40\', \'37\', \'21\', \'12\', \'15\', \'4\', \'31\', \'18\', \'7\', \'39\', \'5\', \'22\', \'42\', \'64\',\'65\',\'66\',\'68\') ; create or replace table snitch_db.maplemonk.offline_metrics_shivera as select * from snitch_db.maplemonk.offline_metrics where lower(PARTNER) IN (\'shivera lifestyle\') ; create or replace table snitch_db.maplemonk.offline_master_shivera as select * from snitch_db.maplemonk.offline_master where lower(PARTNER) IN (\'shivera lifestyle\'); CREATE OR REPLACE TABLE snitch_db.maplemonk.Offline_metrics_warehouse_stock AS SELECT a.*, b.CATEGORY as Product_type, b.OCCASSION_NEW AS OCCASSION, b.DESIGNS AS PRINT_DESIGN, b.COLLAR_NEW AS COLLAR, b.MATERIAL_NEW AS MATERIAL, b.SLEEVE_TYPE, b.FIT, b.STYLE, b.COLOR, b.CLOSURE, b.LENGTH, c.image_link FROM snitch_db.maplemonk.availability_master_v2 a LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) AS rn FROM snitch_db.maplemonk.metafields_data ) WHERE rn = 1 ) b ON LOWER(a.sku_group) = LOWER(b.sku_group) LEFT JOIN ( SELECT * FROM ( WITH product_images AS ( SELECT DISTINCT id, REPLACE(A.value:src, \'\"\', \'\') AS src, REPLACE(A.value:position, \'\"\', \'\') AS pst FROM snitch_db.maplemonk.shopifyindia_new_products, LATERAL FLATTEN(INPUT => IMAGES) A WHERE REPLACE(A.value:position, \'\"\', \'\') = \'1\' ) SELECT b.sku_group, a.src AS image_link, ROW_NUMBER() OVER (PARTITION BY b.sku_group ORDER BY b.sku_group) AS rn FROM product_images a LEFT JOIN snitch_db.maplemonk.availability_master_v2 b ON a.id = b.id ) WHERE rn = 1 ) c ON LOWER(a.sku_group) = LOWER(c.sku_group); Create or replace table snitch_db.maplemonk.Offline_metrics as SELECT A.*, B.AM, B.RM, B.NSM, B.CITY, B.STATE, B.REGION, B.partner FROM snitch_db.maplemonk.Offline_Detailed_Summary AS A LEFT JOIN snitch_db.maplemonk.master_offine AS B ON A.BRANCH_CODE = B.\"BRANCH CODE\" WHERE A.marketplace_mapped NOT LIKE \'%WH%\' ; Create Or REPLACE Table snitch_db.maplemonk.Offline_Inventory_aging as WITH InventoryAging AS ( SELECT branch_code, BRANCH_NAME, REVERSE(SUBSTRING(REVERSE(ADDLITEMCODE), CHARINDEX(\'-\', REVERSE(ADDLITEMCODE)) + 1)) AS sku_group, SUM(stock_qty) AS total_inventory, DATEDIFF(DAY, TO_DATE(lot_pur_date, \'DD/MM/YYYY\'), CURRENT_DATE) AS Age FROM snitch_db.maplemonk.logicerp23_24_get_stock_in_hand WHERE DATE = CURRENT_DATE AND ADDLITEMCODE NOT LIKE (\'CB%\') GROUP BY branch_code, REVERSE(SUBSTRING(REVERSE(ADDLITEMCODE), CHARINDEX(\'-\', REVERSE(ADDLITEMCODE)) + 1)), TO_DATE(lot_pur_date, \'DD/MM/YYYY\'), BRANCH_NAME ), WeightedAging AS ( SELECT branch_code, BRANCH_NAME, sku_group, SUM(total_inventory * Age) AS total_weighted_age, SUM(total_inventory) AS total_inventory FROM InventoryAging GROUP BY branch_code, sku_group,BRANCH_NAME ), age as ( SELECT branch_code, BRANCH_NAME, sku_group, total_inventory, CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) AS final_weighted_age, CASE WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 30 THEN \'0-30\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 60 THEN \'31-60\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 90 THEN \'61-90\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 180 THEN \'91-180\' WHEN CAST((total_weighted_age * 1.0 / NULLIF(total_inventory, 0)) AS DECIMAL(10, 2)) <= 360 THEN \'181-360\' ELSE \'>360\' END AS aging_interval FROM WeightedAging ORDER BY branch_code, sku_group,BRANCH_NAME ), meta as (Select * from (SELECT *, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) AS rn FROM snitch_db.maplemonk.metafields_data)where rn=1) select a.*, b.CATEGORY from age a left join meta b on LOWER(a.sku_group)=LOWER(b.sku_group); Create Or REPLACE Table snitch_db.maplemonk.Offline_Inventory_aging_shivera as select * from snitch_db.maplemonk.Offline_Inventory_aging where BRANCH_CODE IN (\'17\', \'38\', \'28\', \'36\', \'24\', \'26\', \'23\', \'40\', \'37\', \'21\', \'12\', \'15\', \'4\', \'31\', \'18\', \'7\', \'39\', \'5\', \'22\', \'42\', \'64\',\'65\',\'66\',\'68\') ; create or replace table snitch_db.maplemonk.offline_metrics_shivera as select * from snitch_db.maplemonk.offline_metrics where lower(PARTNER) IN (\'shivera lifestyle\') ; create or replace table snitch_db.maplemonk.offline_master_shivera as select * from snitch_db.maplemonk.offline_master where lower(PARTNER) IN (\'shivera lifestyle\'); create or replace table snitch_db.maplemonk.offline_metrics_chennai as select * from snitch_db.maplemonk.offline_metrics where lower(branch_code) IN (\'53\',\'84\',\'110\') ; create or replace table snitch_db.maplemonk.offline_master_chennai as select * from snitch_db.maplemonk.offline_master where branch_code IN (\'53\',\'84\',\'110\'); CREATE or replace TABLE snitch_db.maplemonk.Offline_Detailed_Summary_R2R AS SELECT A.*, B.AM, B.RM, B.NSM, B.CITY, B.STATE, B.REGION, B.partner, B.\"Rent \" ::INT AS RENT, B.\"Size \"::INT AS SIZE FROM snitch_db.maplemonk.Offline_Detailed_Summary AS A LEFT JOIN snitch_db.maplemonk.offline_store_details AS B ON A.BRANCH_CODE = B.\"BRANCH CODE\" WHERE A.marketplace_mapped NOT LIKE \'%- WH -%\' AND B.\"Rent \" =B.\"Rent \" ::INT ; CREATE OR REPLACE TABLE OFFLINE_METRICS_KJFASHIONS AS SELECT * FROM SNITCH_db.maplemonk.offline_metrics WHERE UPPER(PARTNER) = \'KJ FASHION\';",
